        border-bottom: 1px solid rgba(148, 163, 184, 0.16);
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        padding: 8px 12px;
        border-radius: 999px;
        background: rgba(255, 255, 255, 0.75);
        color: var(--accent-strong);
        font-size: 0.8rem;
        font-weight: 700;
        letter-spacing: 0.04em;
        text-transform: uppercase;
      }

      h1 {
        margin: 18px 0 10px;
        font-size: clamp(2rem, 5vw, 2.7rem);
        line-height: 1.05;
      }

      .subtitle {
        margin: 0;
        font-size: 1rem;
        line-height: 1.65;
        color: var(--muted);
        max-width: 52ch;
      }

      .card__body {
        padding: 28px;
      }

      .form-field {
        display: grid;
        gap: 16px;
      }

      .field-label {
        margin: 0;
        font-size: 1.08rem;
        font-weight: 700;
      }

      .options {
        display: grid;
        gap: 14px;
      }

      .option {
        position: relative;
      }

      .option input {
        position: absolute;
        opacity: 0;
        pointer-events: none;
      }

      .option label {
        display: flex;
        align-items: center;
        gap: 14px;
        width: 100%;
        padding: 16px 18px;
        border: 1px solid rgba(148, 163, 184, 0.28);
        border-radius: 18px;
        background: #fff;
        cursor: pointer;
        transition: transform 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;
      }

      .option label:hover {
        transform: translateY(-1px);
        border-color: rgba(79, 70, 229, 0.4);
        box-shadow: 0 12px 24px rgba(15, 23, 42, 0.08);
      }

      .radio-mark {
        width: 22px;
        height: 22px;
        border-radius: 50%;
        border: 2px solid #cbd5e1;
        display: inline-grid;
        place-items: center;
        flex: 0 0 22px;
        transition: border-color 0.18s ease, background 0.18s ease;
      }

      .radio-mark::after {
        content: "";
        width: 10px;
        height: 10px;
        border-radius: 50%;
        background: #fff;
        transform: scale(0);
        transition: transform 0.18s ease;
      }

      .option-text {
        display: grid;
        gap: 3px;
      }

      .option-title {
        font-weight: 700;
      }

      .option-caption {
        color: var(--muted);
        font-size: 0.94rem;
      }

      .option input:checked + label {
        border-color: rgba(79, 70, 229, 0.45);
        background: linear-gradient(180deg, rgba(79, 70, 229, 0.08), rgba(79, 70, 229, 0.03));
        box-shadow: 0 16px 32px rgba(79, 70, 229, 0.12);
      }

      .option input:checked + label .radio-mark {
        border-color: var(--accent);
        background: var(--accent);
      }

      .option input:checked + label .radio-mark::after {
        transform: scale(1);
      }

      .actions {
        margin-top: 26px;
        display: flex;
        align-items: center;
        gap: 14px;
        flex-wrap: wrap;
      }

      .submit-button {
        border: 0;
        border-radius: 999px;
        padding: 14px 22px;
        font: inherit;
        font-weight: 700;
        color: #fff;
        background: linear-gradient(135deg, var(--accent), var(--accent-strong));
        cursor: pointer;
        box-shadow: 0 16px 26px rgba(79, 70, 229, 0.28);
        transition: transform 0.18s ease, box-shadow 0.18s ease;
      }

      .submit-button:hover {
        transform: translateY(-1px);
        box-shadow: 0 18px 30px rgba(79, 70, 229, 0.33);
      }

      .submit-button:active {
        transform: translateY(0);
      }

      .helper-text {
        color: var(--muted);
        font-size: 0.92rem;
      }

      .status {
        margin-top: 16px;
        min-height: 1.5em;
        font-size: 0.95rem;
        font-weight: 600;
        color: var(--accent-strong);
      }

      @media (max-width: 600px) {
        .card__hero,
        .card__body {
          padding: 22px;
        }
      }
    </style>
  </head>
  <body>
    <div id="app"></div>

    <script>
      const options = [
        {
          id: "email",
          value: "Email",
          caption: "Best for detailed updates and summaries."
        },
        {
          id: "sms",
          value: "SMS",
          caption: "Ideal for short, time-sensitive alerts."
        },
        {
          id: "push",
          value: "Push Notifications",
          caption: "Great for real-time reminders on your device."
        }
      ];

      const RadioOption = ({ id, value, caption }) => `
        <div class="option">
          <input type="radio" id="${id}" name="notificationPreference" value="${value}" required />
          <label for="${id}">
            <span class="radio-mark" aria-hidden="true"></span>
            <span class="option-text">
              <span class="option-title">${value}</span>
              <span class="option-caption">${caption}</span>
            </span>
          </label>
        </div>
      `;

      const NotificationForm = () => `
        <form id="notification-form">
          <div class="form-field">
            <p class="field-label">How do you prefer to receive notifications?</p>
            <div class="options" role="radiogroup" aria-labelledby="notification-question">
              ${options.map((option) => RadioOption(option)).join("")}
            </div>
          </div>
          <div class="actions">
            <button class="submit-button" type="submit">Submit</button>
            <span class="helper-text">Choose one option to continue.</span>
          </div>
          <div class="status" id="status" aria-live="polite"></div>
        </form>
      `;

      const App = () => `
        <main class="page-shell">
          <section class="card" aria-labelledby="page-title">
            <div class="card__hero">
              <span class="eyebrow">Preferences</span>
              <h1 id="page-title">Choose your notification channel</h1>
              <p class="subtitle">
                Set a single preferred method so we can send updates in the format that works best for you.
              </p>
            </div>
            <div class="card__body">
              ${NotificationForm()}
            </div>
          </section>
        </main>
      `;

      document.getElementById("app").innerHTML = App();

      const form = document.getElementById("notification-form");
      const status = document.getElementById("status");
      const question = document.querySelector(".field-label");
      question.id = "notification-question";

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        const selected = form.querySelector('input[name="notificationPreference"]:checked');
        status.textContent = selected
          ? `Preference saved: ${selected.value}.`
          : "Please select a notification method.";
      });
    </script>
  </body>
</html>
